INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q96405325', 'Sergeants'' Coup', 'The Sergeants'' Coup was a military coup d''état in Sierra Leone that occurred on 18 April 1968 against Chairman of the National Reformation Council (NRC) and acting Governor-General of Sierra Leone Brigadier Andrew Juxon-Smith, who declared himself the interim leader the year prior. The coup was led by Brigadier John Amadu Bangura who briefly ruled as head of state before handing power over to Siaka Stevens, who had won the 1967 general election.', 1968, 4, 18, NULL, NULL, NULL, 'day', '18 April 1968', 26, 'https://en.wikipedia.org/wiki/Sergeants''_Coup_(Sierra_Leone)'),
  ('Q795269', 'Sierra Leone Civil War', 'The Sierra Leone Civil War (1991–2002) was a civil war in Sierra Leone that began on 23 March 1991 when the Revolutionary United Front (RUF), with support from the special forces of Liberian dictator Charles Taylor, the National Patriotic Front of Liberia (NPFL), intervened in Sierra Leone in an attempt to overthrow the Joseph Momoh government. The resulting civil war lasted almost 11 years, and had over 50,000, up to 70,000, casualties in total; an estimated 2.5 million people were displaced during the conflict, and widespread atrocities occurred.', 1991, 3, 23, 2002, 1, 18, 'day', '23 March 1991 – 18 January 2002', 70, 'https://en.wikipedia.org/wiki/Sierra_Leone_Civil_War'),
  ('Q16822144', '1992 Sierra Leonean coup d''état', 'The 1992 Sierra Leonean coup d''état was a coup d''état against the government of Sierra Leone by a group of young military officers led by 25-year-old Captain Valentine Strasser on 29 April 1992. Strasser took control of the government, deposing President Joseph Saidu Momoh.', 1992, 4, 29, NULL, NULL, NULL, 'day', '29 April 1992', 39, 'https://en.wikipedia.org/wiki/1992_Sierra_Leonean_coup_d''%C3%A9tat'),
  ('Q15989108', 'Western African Ebola virus epidemic', 'The 2013–2016 epidemic of Ebola virus disease, centered in West Africa, was the most widespread outbreak of the disease in history. It caused major loss of life and socioeconomic disruption in the region, mainly in Guinea, Liberia and Sierra Leone.', 2013, 12, NULL, 2016, 6, NULL, 'month', 'December 2013 – June 2016', 78, 'https://en.wikipedia.org/wiki/Western_African_Ebola_epidemic'),
  ('Q36687031', 'Sierra Leone mudslides', 'On the morning of August 14, 2017, significant mudflow events occurred in and around the capital city of Freetown in Sierra Leone. Following three days of torrential rainfall, mass wasting of mud and debris damaged or destroyed hundreds of buildings in the city, killing 1,141 people and leaving more than 3,000 homeless.', 2017, 8, 14, NULL, NULL, NULL, 'day', '14 August 2017', 53, 'https://en.wikipedia.org/wiki/2017_Sierra_Leone_mudslides'),
  ('Q109423195', '2021 Sierra Leone oil tanker collision', 'On 5 November 2021 a collision between a petrol fuel tanker and a lorry at a busy junction of Sierra Leone''s capital, Freetown, resulted in an explosion and a fire that caused 154 deaths and 304 injuries, overwhelming the city''s medical services.', 2021, 11, 5, NULL, NULL, NULL, 'day', '5 November 2021', 56, 'https://en.wikipedia.org/wiki/Freetown_fuel_tanker_explosion');

